window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[178]={"id":"178","numero":178,"titre":"Risques émergents","objectifs":[{"id":"178-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un risque émergent","contenu":"<p>Un <strong><span class=\"kw-def\">risque émergent</span></strong> se définit comme tout risque à la fois <strong><span class=\"kw-def\">nouveau</span></strong> et <strong><span class=\"kw-def\">croissant</span></strong> — <span class=\"kw-clinique\">les</span> deux conditions sont requises.</p>\n      <p>Parmi <span class=\"kw-clinique\">les</span> risques biologiques, sont au 1<sup>er</sup> plan :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">risques environnementaux</span> ;</li>\n        <li><span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">maladies infectieuses</span> — dont la <strong>majorité viennent de l'animal</strong> (<span class=\"kw-def\">zoonoses</span>).</li>\n      </ul>\n      <div class=\"callout callout-info\">⚠️ Piège classique : « <span class=\"kw-def\">nouveau</span> » seul ne suffit pas, « <span class=\"kw-def\">croissant</span> » seul non plus. La définition ex<span class=\"kw-chiffre\">ige</span> <span class=\"kw-clinique\">les</span> <strong>deux</strong> caractères <span class=\"kw-alerte\">réunis</span>.</div>","frequence":0},{"id":"178-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une infection émergente","contenu":"<p>Une <strong><span class=\"kw-def\">maladie infectieuse émergente</span></strong> (MIE) est une maladie infectieuse (ou présumée infectieuse) à la fois <strong>nouvelle</strong> et <strong>en augmentation</strong>, touchant <strong>l'homme, l'animal ou <span class=\"kw-clinique\">les</span> deux</strong>.</p>\n      <p>Une MIE peut correspondre à <strong>trois situations</strong> :</p>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Précisions</th><th>Exemples</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Entité clinique d'origine infectieuse <strong>nouvellement apparue ou identifiée</strong></td>\n            <td>Pathologie jamais décrite ou identifiée auparavant</td>\n            <td>Infections respiratoires graves à <span class=\"kw-etio\">coronavirus</span> : <span class=\"kw-etio\">SRAS</span> (2003), <span class=\"kw-etio\">MERS</span> (Moyen-Orient depuis 2012), <span class=\"kw-etio\">COVID-19</span> (depuis fin 2019)</td>\n          </tr>\n          <tr>\n            <td>Maladie <strong>connue</strong> devenue MIE</td>\n            <td><strong><span class=\"kw-def\">Incidence</span> :</strong> en augmentation<br><strong>Modification :</strong> des caractéristiques cliniques ou évolutives dans un espace / une population donnée<br><strong>Nouveaux variants</strong> de l'agent : modification de la <span class=\"kw-alerte\">sensibilité aux anti-infectieux</span> (ex. BHR à risque épidémique) ; modifications antigéniques (moindre efficacité vaccinale ; nouveaux mécanismes pathogéniques type production de toxine)</td>\n            <td><span class=\"kw-etio\">West Nile</span> ; <span class=\"kw-etio\">Chikungunya</span> ; <span class=\"kw-etio\">Zika</span> ; <span class=\"kw-etio\">Ebola</span></td>\n          </tr>\n          <tr>\n            <td>Maladie identifiée dont <span class=\"kw-clinique\">les</span> <strong>conditions d'expansion sont réunies</strong></td>\n            <td>Optique d'<strong>anticipation</strong></td>\n            <td>Implantation d'<span class=\"kw-etio\"><em>Aedes albopictus</em></span> dans le Sud de la France — moustique vecteur de la <span class=\"kw-etio\">dengue</span> et du <span class=\"kw-etio\">Chikungunya</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Piège classique : une MIE n'est <strong>pas forcément une maladie nouvelle</strong>. Une maladie connue qui réémerge ou dont <span class=\"kw-clinique\">les</span> conditions d'expansion changent est une MIE — exclure une maladie « pas nouvelle » est un <span class=\"kw-alerte\">faux raisonnement</span> en QRM.</div>\n      <div class=\"callout callout-info\"><strong>Pour info (rang C — hors programme strict).</strong> L'émergence est un phénomène <span class=\"kw-def\">dynamique et complexe</span>, résultant de l'interaction de la triade <strong>Hôte ↔ Agent <span class=\"kw-ttt\">biologique</span> ↔ Environnement</strong>. Principaux facteurs favorisants : changements environnementaux (climat, déforestation, pression de sélection antibiotique) ; <span class=\"kw-clinique\">évolution</span> démographique et urbanisation ; mondialisation des échanges et transports internationaux ; <span class=\"kw-def\">contact</span> homme / faune sauvage ou animaux domestiques ; modifications économiques et sociales ; pratiques médicales.</div>","frequence":0},{"id":"178-3","rang":"B","rubrique":"Définition","titre":"Citer les principaux agents infectieux émergents ou réémergents","contenu":"<p><span class=\"kw-clinique\">Les</span> agents <span class=\"kw-etio\">infectieux</span> émergents ou réémergents se répartissent entre ceux <strong>communs</strong> aux MIE et aux maladies hautement transmissibles, et ceux <strong>spécifiques</strong> aux MIE.</p>\n      <table >\n        <thead>\n          <tr><th>Groupe</th><th>Agents</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Communs<br>(<span class=\"kw-def\">MIE</span> et maladies hautement transmissibles)</td>\n            <td>\n              <strong>Fièvres hémorragiques virales :</strong> <span class=\"kw-etio\">Ebola</span> ; <span class=\"kw-etio\">Marburg</span> ; <span class=\"kw-etio\">Crimée-Congo</span> ; <span class=\"kw-etio\">Lassa</span><br>\n              <strong>Coronavirus émergents graves :</strong> <span class=\"kw-etio\">SRAS</span> ; <span class=\"kw-etio\">MERS</span> ; <span class=\"kw-etio\">COVID-19</span><br>\n              <strong><span class=\"kw-etio\">Tuberculose</span> résistante :</strong> multi-résistante (<span class=\"kw-alerte\">MDR</span>) ou ultra-résistante (<span class=\"kw-alerte\">XDR</span>)<br>\n              <strong>Grippes :</strong> <span class=\"kw-etio\">grippe aviaire</span> et <span class=\"kw-etio\">grippe pandémique</span> (<span class=\"kw-etio\"><em>Myxovirus influenzae</em> H5N1</span> et futures souches porteuses d'autres H et N)\n            </td>\n          </tr>\n          <tr>\n            <td>Spécifiques aux <span class=\"kw-def\">MIE</span></td>\n            <td>\n              <strong>Encéphalites virales :</strong> virus <span class=\"kw-etio\">West-Nile</span> ; virus <span class=\"kw-etio\">Nipah</span> ; virus <span class=\"kw-etio\">Hendra</span><br>\n              <strong>Arboviroses</strong> (transmises par <span class=\"kw-etio\"><em>Aedes aegypti</em></span> et <span class=\"kw-etio\"><em>Aedes albopictus</em></span>) : <span class=\"kw-etio\">Chikungunya</span> ; <span class=\"kw-etio\">dengue</span> ; <span class=\"kw-etio\">Zika</span><br>\n              <strong><span class=\"kw-clinique\">IST</span> :</strong> <span class=\"kw-etio\">VHC</span> ; <span class=\"kw-etio\">syphilis</span> ; <span class=\"kw-etio\">lymphogranulomatose vénérienne</span><br>\n              <strong>SHU</strong> (syndrome hémolytique et urémique) : <span class=\"kw-etio\"><em>E. coli</em> O157:H7</span><br>\n              <strong>Infections graves à <span class=\"kw-etio\"><em>Clostridium difficile</em></span> :</strong> <span class=\"kw-etio\"><em>C. difficile</em> O27 hypervirulent</span><br>\n              <strong>BHR</strong> (bactéries hautement résistantes) : entérobactéries productrices de <span class=\"kw-alerte\">carbapénémase</span> ; <span class=\"kw-etio\">entérocoque</span> résistant aux <span class=\"kw-alerte\">glycopeptides</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-etio\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span> · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte · 166 — <span class=\"kw-etio\">Grippe</span> · 167 — Hépatites virales · 169 — VIH · 176 — <span class=\"kw-clinique\">Diarrhée</span> infectieuse</em></p>","frequence":0},{"id":"178-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une maladie hautement transmissible","contenu":"<p>Une <strong><span class=\"kw-def\">maladie hautement transmissible</span></strong> est une pathologie à <strong><span class=\"kw-def\">haut potentiel infectieux</span></strong>. Le terme regroupe un ensemble de maladies infectieuses qui partagent des <strong>caractéristiques communes</strong> :</p>\n      <ul>\n        <li><span class=\"kw-alerte\"><strong>Transmission interhumaine</strong></span> ;</li>\n        <li><span class=\"kw-alerte\"><strong>Contagiosité élevée</strong></span> ;</li>\n        <li><span class=\"kw-alerte\">Létalité potentielle</span> ;</li>\n        <li><strong>Traitement inexistant ou d'efficacité incertaine</strong> ;</li>\n        <li><strong><span class=\"kw-def\">Absence de vaccin</span></strong>.</li>\n      </ul>\n      <p>Ces caractéristiques font peser un risque de <span class=\"kw-alerte\">diffusion communautaire et/ou nosocomiale</span> → elles nécessitent la mise en place de <strong><span class=\"kw-def\">mesures de contrôle spécifiques</span></strong>.</p>\n      <div class=\"callout callout-info\">⚠️ À retenir : c'est le <strong>cumul</strong> des caractéristiques (transmission interhumaine + contagiosité + létalité + absence de traitement/vaccin) qui définit le haut potentiel transmissible, pas un critère isolé.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 4 — Sécurité du patient, gestion des risques</em></p>","frequence":0},{"id":"178-5","rang":"B","rubrique":"Définition","titre":"Citer les principaux agents infectieux responsables de maladies hautement transmissibles","contenu":"<p><span class=\"kw-clinique\">Les</span> agents responsables de maladies hautement transmissibles se répartissent entre ceux <strong>communs</strong> aux MIE et ceux <strong>spécifiques</strong> aux maladies hautement transmissibles.</p>\n      <table >\n        <thead>\n          <tr><th>Groupe</th><th>Agents</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Communs<br>(partagés avec <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">MIE</span>)</td>\n            <td>\n              <span class=\"kw-etio\">Fièvres hémorragiques virales</span><br>\n              Infections émergentes graves à <span class=\"kw-etio\">coronavirus</span><br>\n              <span class=\"kw-etio\">Tuberculose</span> <span class=\"kw-alerte\">MDR</span> ou <span class=\"kw-alerte\">XDR</span><br>\n              Souches émergentes de <span class=\"kw-etio\">grippe</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Spécifiques aux <span class=\"kw-def\">maladies hautement transmissibles</span></td>\n            <td>\n              <span class=\"kw-etio\"><strong>Variole</strong> et autres orthopoxvirus</span> (ex. <span class=\"kw-etio\">Monkeypox</span>)<br>\n              <span class=\"kw-etio\"><strong>Peste</strong></span> dans sa <span class=\"kw-alerte\">forme pulmonaire</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Piège classique : pour la peste, c'est la <span class=\"kw-alerte\">forme pulmonaire</span> qui relève des maladies hautement transmissibles (transmission interhumaine par voie respiratoire).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte · 166 — <span class=\"kw-etio\">Grippe</span></em></p>","frequence":0},{"id":"178-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition du bioterrorisme","contenu":"<p>Le <strong><span class=\"kw-def\">bioterrorisme</span></strong> est l'<strong>utilisation</strong> — ou la <strong><span class=\"kw-def\">menace d'utilisation</span></strong> — d'<strong>agents biologiques <span class=\"kw-def\">comme une arme</span></strong>, en vue d'<span class=\"kw-alerte\">induire une maladie ou la mort</span> chez <span class=\"kw-clinique\">les</span> hommes, les animaux et/ou les plantes.</p>\n      <p>Sous le terme <strong>« agent <span class=\"kw-ttt\">biologique</span> »</strong>, on regroupe :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">agents infectieux naturels</span> : bactéries, virus, parasites, champignons ;</li>\n        <li><span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">toxines</span> produites par ces agents <span class=\"kw-etio\">infectieux</span> naturels ;</li>\n        <li><span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">agents infectieux génétiquement modifiés</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">⚠️ Piège classique : le bioterrorisme inclut la <strong><span class=\"kw-alerte\">menace</span></strong> d'utilisation (pas seulement l'usage effectif) et englobe <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-etio\">agents génétiquement modifiés</span></strong> — deux points souvent oubliés.</div>","frequence":0},{"id":"178-7","rang":"B","rubrique":"Définition","titre":"Connaître la classification des principaux agents biologiques utilisables dans un contexte de bioterrorisme","contenu":"<p><span class=\"kw-clinique\">Les</span> principaux agents biologiques du bioterrorisme sont classés selon leur <strong>niveau de risque</strong>, par ordre <strong>décroissant</strong> — catégories A, B puis C.</p>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Définition</th><th>Agents</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Catégorie A</span></td>\n            <td>Maladies <strong>létales et hautement transmissibles</strong>, ou <strong>faciles à disséminer</strong> — priorité absolue</td>\n            <td>\n              <strong>Bactéries :</strong> <span class=\"kw-etio\"><em>Bacillus anthracis</em></span> ; <span class=\"kw-etio\"><em>Yersinia pestis</em></span> ; <span class=\"kw-etio\"><em>Francisella tularensis</em></span><br>\n              <strong>Virus :</strong> <span class=\"kw-etio\">virus de la variole</span> ; <span class=\"kw-etio\">Filovirus (Ebola, Marburg)</span> ; <span class=\"kw-etio\">Arenavirus (Lassa, Junin)</span><br>\n              <strong>Toxines :</strong> <span class=\"kw-etio\">toxines de <em>Clostridium botulinum</em> (toxines botuliques)</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Catégorie B</span></td>\n            <td>Pathogénicité <strong>modérée</strong>, <span class=\"kw-def\">mortalité</span> plus faible</td>\n            <td>\n              <strong>Bactéries :</strong> <span class=\"kw-etio\"><em>Coxiella burnetii</em></span> ; <span class=\"kw-etio\"><em>Brucella</em></span> ; <span class=\"kw-etio\"><em>Burkholderia mallei</em> et <em>pseudomallei</em></span><br>\n              <strong>Virus :</strong> <span class=\"kw-etio\">Alphavirus (encéphalites équines du Venezuela, de l'Est et de l'Ouest)</span><br>\n              <strong>Toxines :</strong> <span class=\"kw-etio\">ricine</span> ; <span class=\"kw-etio\">toxine epsilon de <em>Clostridium perfringens</em></span> ; <span class=\"kw-etio\">entérotoxine B staphylococcique</span><br>\n              <strong>Pathogènes transmis par l'eau et <span class=\"kw-clinique\">les</span> aliments :</strong> <span class=\"kw-etio\"><em>Salmonella</em></span> ; <span class=\"kw-etio\"><em>Shigella dysenteriae</em></span> ; <span class=\"kw-etio\"><em>E. coli</em> O157:H7</span> ; <span class=\"kw-etio\"><em>Vibrio cholerae</em></span> ; <span class=\"kw-etio\"><em>Cryptosporidium parvum</em></span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Catégorie C</span></td>\n            <td>Maladies infectieuses <strong>émergentes</strong> faciles à disséminer</td>\n            <td>Virus <span class=\"kw-etio\">Nipah</span> ; <span class=\"kw-etio\">Hantavirus</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Voies de contamination possibles :</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\"><strong>Percutanée</strong></span> ;</li>\n        <li><span class=\"kw-alerte\"><strong>Digestive</strong> — ingestion d'eau ou d'aliments</span> ;</li>\n        <li><span class=\"kw-alerte\"><strong>Aérosols</strong></span> — particules de <span class=\"kw-chiffre\">1 à 5 µm</span> de <span class=\"kw-clinique\">diamètre</span>, susceptibles de rester en suspension dans l'<span class=\"kw-def\">air</span> plusieurs heures et, en cas d'inhalation, d'atteindre <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">alvéoles pulmonaires</span>.</li>\n      </ul>\n      <p><strong>Classement selon la conséquence :</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\"><strong>Agents létaux :</strong></span> <span class=\"kw-etio\"><em>Bacillus anthracis</em></span>, <span class=\"kw-etio\"><em>Yersinia pestis</em></span>, <span class=\"kw-etio\">variole</span>… ;</li>\n        <li><strong>Agents incapacitants :</strong> <span class=\"kw-etio\"><em>Coxiella burnetii</em></span>, <span class=\"kw-etio\"><em>Brucella</em></span>, <span class=\"kw-etio\">entérotoxine B staphylococcique</span>…</li>\n      </ul>\n      <div class=\"callout callout-info\">⚠️ À retenir : <span class=\"kw-clinique\">les</span> agents à connaître en priorité sont ceux de la <span class=\"kw-alerte\">catégorie A</span>. Ne pas confondre les <strong>toxines botuliques</strong> (catégorie A) avec les autres toxines — ricine, entérotoxine B (catégorie B).</div>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-178.pdf","label":"Collège Pilly — Risques émergents (item 178, PDF)"}],"cards":[{"i":"0ff928125352","n":178,"o":"178-1","u":"Définition","t":"Connaître la définition d’un risque émergent","q":"En ce qui concerne la définition d'un risque émergent, quel est le piège classique à éviter pour les étudiants ?","a":"<p>Le piège classique est de considérer qu'un risque est \"émergent\" s'il est seulement <strong>nouveau</strong> ou s'il est seulement <strong>croissant</strong>. La définition exige impérativement que ces <strong>deux caractères soient réunis</strong> simultanément.</p>"},{"i":"6f81049a1834","n":178,"o":"178-1","u":"Définition","t":"Connaître la définition d’un risque émergent","q":"Quelle est la définition d'un risque émergent en santé ?","a":"<p>Un risque émergent se définit comme tout risque à la fois <strong>nouveau ET croissant</strong>. Ces deux conditions sont impérativement requises.</p>"},{"i":"ada1fd928d7f","n":178,"o":"178-1","u":"Définition","t":"Connaître la définition d’un risque émergent","q":"Quels sont les principaux types de risques émergents biologiques ?","a":"<ul><li>Les <strong>risques environnementaux</strong>.</li><li>Les <strong>maladies infectieuses</strong>, dont la majorité sont des zoonoses (d'origine animale).</li></ul>"},{"i":"041db1b35d1c","n":178,"o":"178-2","u":"Définition","t":"Connaître la définition d’une infection émergente","q":"Est-ce qu'une maladie connue peut être considérée comme une maladie infectieuse émergente (MIE) ?","a":"<p>Oui, absolument. Une maladie connue peut être une MIE si son <strong>incidence est en augmentation</strong>, si ses <strong>caractéristiques ont changé</strong>, ou si les <strong>conditions de son expansion sont nouvelles</strong> ou réunies. Il est important de ne pas exclure une maladie car elle n'est pas \"nouvelle\" dans ce contexte.</p>"},{"i":"5662648bc84d","n":178,"o":"178-2","u":"Définition","t":"Connaître la définition d’une infection émergente","q":"Quelle est la définition d'une maladie infectieuse émergente (MIE) ?","a":"<p>Une maladie infectieuse émergente (MIE) est une maladie infectieuse, ou présumée infectieuse, à la fois <strong>nouvelle et en augmentation</strong>, touchant l'homme, l'animal ou les deux.</p>"},{"i":"cee04c26728c","n":178,"o":"178-2","u":"Définition","t":"Connaître la définition d’une infection émergente","q":"Quels sont les trois scénarios conduisant à la définition d'une maladie infectieuse émergente (MIE) ?","a":"<ul><li>Une entité clinique d'origine infectieuse <strong>nouvellement apparue ou identifiée</strong> (pathologie jamais décrite).</li><li>Une maladie connue dont l'<strong>incidence est en augmentation</strong> ou dont les <strong>caractéristiques cliniques ou évolutives ont changé</strong> dans une population donnée.</li><li>Une maladie identifiée dont les <strong>conditions d'expansion sont réunies ou anticipées</strong> (par exemple, un vecteur).</li></ul>"},{"i":"38452427bc17","n":178,"o":"178-4","u":"Définition","t":"Connaître la définition d’une maladie hautement transmissible","q":"Quel élément est essentiel pour caractériser le haut potentiel transmissible d'une maladie ?","a":"<p>C'est le <strong>cumul des caractéristiques</strong> (transmission interhumaine, contagiosité, létalité, absence de traitement/vaccin) qui définit le haut potentiel transmissible d'une maladie, et non un critère isolé.</p>"},{"i":"98dabacc0f1f","n":178,"o":"178-4","u":"Définition","t":"Connaître la définition d’une maladie hautement transmissible","q":"Quelles sont les caractéristiques communes des maladies hautement transmissibles ?","a":"<ul><li><strong>Transmission interhumaine</strong> avérée</li><li><strong>Contagiosité élevée</strong></li><li><strong>Létalité potentielle</strong></li><li><strong>Traitement inexistant ou d'efficacité incertaine</strong></li><li><strong>Absence de vaccin</strong></li></ul>"},{"i":"ec925b2e2acf","n":178,"o":"178-4","u":"Définition","t":"Connaître la définition d’une maladie hautement transmissible","q":"Quelle est la définition d'une maladie hautement transmissible ?","a":"<p>Une maladie hautement transmissible est une <strong>pathologie à haut potentiel infectieux</strong>. Elle regroupe des maladies infectieuses présentant des caractéristiques spécifiques qui font peser un risque de diffusion communautaire ou nosocomial.</p>"},{"i":"27bf56127a49","n":178,"o":"178-6","u":"Définition","t":"Connaître la définition du bioterrorisme","q":"Qu'est-ce qu'un agent biologique dans le cadre du bioterrorisme ?","a":"<p>Sous le terme « agent biologique », on regroupe :</p><ul><li>Les <strong>agents infectieux naturels</strong> : bactéries, virus, parasites, champignons.</li><li>Les <strong>toxines</strong> produites par ces agents infectieux naturels.</li><li>Les <strong>agents infectieux génétiquement modifiés</strong>.</li></ul>"},{"i":"682ec127bb3f","n":178,"o":"178-6","u":"Définition","t":"Connaître la définition du bioterrorisme","q":"Quel est un piège classique concernant la définition du bioterrorisme ?","a":"<p>Un piège classique est d'oublier que le bioterrorisme inclut la <strong>menace d'utilisation</strong> (pas seulement l'usage effectif) et qu'il englobe les <strong>agents génétiquement modifiés</strong>.</p>"},{"i":"adfdc57dfcb4","n":178,"o":"178-6","u":"Définition","t":"Connaître la définition du bioterrorisme","q":"Quelle est la définition du bioterrorisme ?","a":"<p>Le bioterrorisme est l'<strong>utilisation</strong> — ou la <strong>menace d'utilisation</strong> — d'<strong>agents biologiques</strong> comme une arme, en vue d'<strong>induire une maladie ou la mort</strong> chez les hommes, les animaux et/ou les plantes.</p>"}]};